%% Peaucellier Straight-Line Mechanism
clear; clc; close all;

a = 105; b = 40; r = 35;       % Link dimensions (mm)
L = (a^2-b^2)/(2*r);
lim = 2*acos((a-b)/(2*r))-0.01;

omega = 1;                     % rad/s
dt = 0.01;
T = 2*lim/omega;
time = [0:dt:T, T];
theta = -lim + omega*time;

%% Figure
figure('Color','w'); %[output:561be268]
hold on; axis equal; grid on; %[output:561be268]
xlim([-20 190]); ylim([-120 120]); %[output:561be268]
xlabel('X (mm)'); ylabel('Y (mm)'); %[output:561be268]

O2 = [0;0]; O4 = [r;0];
ymax = L*tan(lim/2);

plot([O2(1) O4(1)],[0 0],'k-','LineWidth',2); %[output:561be268]
plot([L L],[-ymax ymax],'k--','LineWidth',1.5); %[output:561be268]

% Links 2–8: green, green, red, blue, blue, blue, blue
colors = [0 .7 0; 0 .7 0; 1 0 0; zeros(4,2) ones(4,1)];
links = gobjects(1,7);

for i = 1:7
    links(i) = plot(nan,nan,'-o','Color',colors(i,:), ... %[output:561be268]
        'LineWidth',3,'MarkerFaceColor',colors(i,:)); %[output:561be268]
end

names = {'O_2,O_3','O_4','C,D','A,B','E,F','G'};
labels = gobjects(1,6);
for i = 1:6
    labels(i) = text(nan,nan,names{i},'FontWeight','bold'); %[output:561be268]
end

%% Animation
clockStart = tic;

for k = 1:numel(time) %[output:group:9b2dd0c8]
    t = theta(k);

    CD = [r*(1+cos(t)); r*sin(t)];
    G = [L; L*tan(t/2)];

    M = (CD+G)/2;
    d = norm(G-CD);
    h = sqrt(max(0,b^2-d^2/4));
    u = (G-CD)/d;
    v = [-u(2);u(1)];

    AB = M+h*v;
    EF = M-h*v;

    endpoints = {O2,AB; O2,EF; O4,CD; AB,CD; ...
                 CD,EF; AB,G; EF,G};

    for i = 1:7
        p = endpoints{i,1}; q = endpoints{i,2};
        set(links(i),'XData',[p(1) q(1)], ... %[output:561be268]
                     'YData',[p(2) q(2)]); %[output:561be268]
    end

    joints = [O2 O4 CD AB EF G];
    for i = 1:6
        set(labels(i),'Position',[joints(:,i)'+[0 7],0]);
    end

    title(sprintf('Input = %.1f° | Speed = 1 rad/s | Time = %.2f s', ...
    rad2deg(t), time(k)));
    drawnow;

    pause(max(0,time(k)-toc(clockStart)));
end %[output:group:9b2dd0c8]

%% Results
fprintf('Output X = %.2f mm\n',L); %[output:9f5ca893]
fprintf('Input range = +/- %.2f deg\n',rad2deg(lim)); %[output:8e64885b]
fprintf('Output stroke = %.2f mm\n',2*ymax); %[output:5656ff6d]
fprintf('Sweep duration = %.2f s\n',T); %[output:62d69b5c]
%%
%% Velocity and Acceleration Analysis

syms theta omega alpha real

% Symbolic equations for output point P
y = L*tan(theta/2);
v = simplify(diff(y,theta)*omega);
acc = simplify(diff(v,theta)*omega + diff(v,omega)*alpha);

disp('Velocity:'); pretty(v) %[output:3b8ecb15] %[output:72dfad78]
disp('Acceleration:'); pretty(acc) %[output:792d2903] %[output:38633184]

% Constant input angular velocity
w = 1;  % rad/s
t = linspace(-lim,lim,200);

% Numerical results
Y = L*tan(t/2);
V = (L/2)*sec(t/2).^2*w;
ACC = (L/2)*sec(t/2).^2.*tan(t/2)*w^2;

% Plot
figure('Color','w'); %[output:1d83d772]
data = {Y,V,ACC};
names = {'Position','Velocity','Acceleration'};
units = {'mm','mm/s','mm/s^2'};

for i = 1:3
    subplot(3,1,i) %[output:1d83d772]
    plot(rad2deg(t),data{i},'LineWidth',1.8)
    grid on
    title(names{i})
    ylabel(units{i})
end

xlabel('Input Angle (deg)') %[output:1d83d772]
sgtitle('Peaucellier Straight-Line Kinematic Analysis') %[output:1d83d772]

